import { TranscribeStreamingClient, StartStreamTranscriptionCommand } from "@aws-sdk/client-transcribe-streaming";

const tokenId = YOUR_TWILIO_ACCESS_TOKEN_ID; // Replace with your Twilio Access Token ID
const location = YOUR_AWS_REGION; // Replace with your AWS region, e.g., 'us-west-2'

let room;
let transcribeStreamingClient;
let transcribeStream;
let audioStreamBuffer;

async function startTranscription() {
  // Configure the AWS Transcribe Streaming Client
  transcribeStreamingClient = new TranscribeStreamingClient({ region: location });

  const startStreamTranscriptionCommand = new StartStreamTranscriptionCommand({
    LanguageCode: "en-US", // Replace with the desired language
    MediaEncoding: "pcm",
    MediaSampleRateHertz: 16000,
    AudioStream: {
      write: data => {
        if (audioStreamBuffer) {
          audioStreamBuffer(data);
        }
      },
      [Symbol.asyncIterator]() {
        // Use a generator function that resolves audio data as chunks and listens for new data
        return {
          next: () => {
            return new Promise(resolve => {
              audioStreamBuffer = resolve;
            });
          },
        };
      }
    }
  });

  // Start Stream Transcription on AWS
  transcribeStream = await transcribeStreamingClient.send(startStreamTranscriptionCommand);

  // Capture transcriptions and display them
  for await (const event of transcribeStream.TranscriptResultStream) {
    console.log(event.Transcript.Results[0].Alternatives[0].Transcript);
  }
}

async function stopTranscription() {
  if (transcribeStreamingClient) {
    transcribeStreamingClient.terminate();
  }
}

function captureAudio(track) {
  const audioContext = new AudioContext();
  const mediaStreamSource = audioContext.createMediaStreamSource(new MediaStream([track]));
  // Connect media stream to a script processor
  const scriptNode = audioContext.createScriptProcessor(512, 1, 1);

  scriptNode.addEventListener("audioprocess", event => {
    const samples = event.inputBuffer.getChannelData(0);
    if (audioStreamBuffer) {
      audioStreamBuffer(samples);
    }
  });

  // Connect the media stream source to the script processor
  mediaStreamSource.connect(scriptNode);
  scriptNode.connect(audioContext.destination);
}

