  room = await Twilio.Video.connect(tokenId, { audio: true, video: false, name: 'my-room' });

  room.on('participantConnected', participant => {
    participant.on('trackSubscribed', track => {
      if (track.kind === 'audio') {
        captureAudio(track.mediaStreamTrack);
      }
    });
  });

  room.localParticipant.audioTracks.forEach(track => {
    captureAudio(track.mediaStreamTrack);
  });
}

