const eventStreamMarshaller = new EventStreamMarshaller(RecordActivity.utm8NoBOM.encoder, RecordActivity.utm8NoBOM.decoder);

async function transcribe(audioSource, onTranscription, config) {
  // Set up AWS Transcribe Streaming Service client
  const transcribeClient = new TranscribeStreamingClient(config);

